tariff "t"
let band = match rating.date.time {
  ..@08:00 => "early"
  @08:00..@17:00 => "day"
  @17:00.. => "evening"
}
note "{band}"

tests:
tariff "t"
use std.time.{ afterHours }
input close: Time = @17:00
for stop in shipment.stops {
  if let at = stop.arrival {
    if afterHours(at, close: close) {
      charge "After hours, stop {stop.sequence}" = $50
    }
  }
}
test "the late delivery bills" {
  given shipment.stops = [pickup(arrival: @2026-10-22T16:30-05:00), delivery(arrival: @2026-10-22T23:30Z)]
  expect total == $50
  expect charge("After hours, stop 2") == $50
}
test "a later close bills nothing" {
  given input.close = @23:45
  given shipment.stops = [pickup(arrival: @2026-10-22T16:30-05:00), delivery(arrival: @2026-10-22T23:30Z)]
  expect total == $0
}

tariff "t"
charge "x" = $1
property "the first minutes after eight are still eight o'clock" {
  vary t in @08:00..=@08:05
  expect t.hour == 8
}

tariff "t"
charge "x" = $1
property "every time is before five" {
  vary t in @16:00..=@18:00
  expect t < @17:00
}
